Given two binary arrays a1[] and a2[] of equal length, find the maximum length of a subarray [i...j] such that the sum of elements from i to j in both arrays is equal, i.e., a1[i] + a1[i+1] + ... + a1[j] == a2[i] + a2[i+1] + ... + a2[j].Examples:  Input: a1[] = [0, 1, 0, 0, 0, 0], a2[] = [1, 0, 1, 0, 0, 1] Output: 4 Explanation: The longest span with same sum is from index 1 to 4.  Input: a1[] = [0, 1, 0, 1, 1, 1, 1], a2[] = [1, 1, 1, 1, 1, 0, 1]Output: 6 Explanation: The longest span with same sum is from index 1 to 6.  Input: a1[] = [0, 0, 0], a2[] = [1, 1, 1]Output: 0  Explanation: There is no span where the sum of the elements in a1[] and a2[] is equal.Try It YourselfTable of Content[Naive Approach] Checking Each Subarray - O(n^2) Time and O(1) Space[Expected Approach] Using Difference Array - O(n) Time and O(n) Space [Alternative Approach] Using Hash Map - O(n) Time and O(n) Space[Naive Approach] Checking Each Subarray - O(n2) Time and O(1) SpaceThe idea is to check all possible subarrays by considering every starting and ending position, calculate the sum for both arrays in each subarray, and keep track of the maximum length where sums are equal.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int equalSumSpan(vector<int> &a1, vector<int> &a2) {
    int n = a1.size();
    int maxLen = 0;

    // Check all possible subarrays
    for (int i = 0; i < n; i++) {
        int prefixSum1 = 0, prefixSum2 = 0;

        for (int j = i; j < n; j++) {

            // Calculate sum for current subarray
            prefixSum1 += a1[j];
            prefixSum2 += a2[j];

            // If sums are equal, update maxLen
            if (prefixSum1 == prefixSum2) {
                maxLen = max(maxLen, j - i + 1);
            }
        }
    }

    return maxLen;
}

int main() {
    vector<int> a1 = {0, 1, 0, 0, 0, 0};
    vector<int> a2 = {1, 0, 1, 0, 0, 1};
    cout << equalSumSpan(a1, a2);
    return 0;
}


